/**
 * Translates API error messages for the web interface. Messages stay English in the code; the
 * catalogue (api.* keys in locales/en.json, generated by `pnpm i18n:sync`) maps each English text,
 * or template with {placeholders}, to a key. Requests without x-fudo-lang get English, so scripts
 * and integrations see stable messages; the machine-readable `error` code never changes.
 */
import { formatMessage } from "@fudo/shared";
import { serverI18n } from "@fudo/notify/server";

interface Entry { key: string; re: RegExp | null; names: string[]; text: string }
let catalogue: { exact: Map<string, string>; templates: Entry[] } | null = null;
let builtAt = 0;

function build() {
  const exact = new Map<string, string>(), templates: Entry[] = [];
  for (const [key, text] of serverI18n().entries("en", "api.")) {
    const names = [...text.matchAll(/\{(\w+)\}/g)].map((m) => m[1]!);
    if (!names.length) { exact.set(text, key); continue; }
    const re = new RegExp("^" + text.split(/\{\w+\}/).map((p) => p.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("(.+?)") + "$", "s");
    templates.push({ key, re, names, text });
  }
  // most specific first: more literal text wins over a generic frame
  templates.sort((a, b) => b.text.replace(/\{\w+\}/g, "").length - a.text.replace(/\{\w+\}/g, "").length);
  return { exact, templates };
}

/** The message in `lang`, or unchanged when it is not in the catalogue. */
export function translateApiText(lang: string | null, text: string): string {
  if (!lang || lang === "en" || !text) return text;
  if (!catalogue || Date.now() - builtAt > 60_000) { catalogue = build(); builtAt = Date.now(); } // picks up edited language files
  const i18n = serverI18n(), look = i18n.lookup(lang);
  const key = catalogue.exact.get(text);
  if (key) return look(key) ?? text;
  for (const t of catalogue.templates) {
    const m = t.re!.exec(text);
    if (!m) continue;
    const params = Object.fromEntries(t.names.map((n, i) => [n, translateApiText(lang, m[i + 1]!)])); // nested known texts translate too
    const target = look(t.key);
    return target ? formatMessage(target, params, lang, i18n.numberLocale(lang)) : text;
  }
  return text;
}

/** The requested language: the web interface sends x-fudo-lang. */
export function requestLang(headers: Record<string, string | string[] | undefined>): string | null {
  const v = headers["x-fudo-lang"];
  const code = Array.isArray(v) ? v[0] : v;
  return code && /^[a-z]{2,3}(-[A-Za-z0-9]{2,8})?$/.test(code) && serverI18n().has(code) ? code : null;
}
